const KEYS:[&str;16]=["positions","normals","colors","indices","uvs","faceIds","vertexIds","edgePositions","edgeIds","edgeUvs","edgeIsSeam","paintTextureBase64","attributes","materials","textures","componentReferences"];
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,message)}
fn admitted(d:RetirementDemand,g:RetainedCloneGrant)->bool{g.maximum_items>0&&g.maximum_copy_bytes>=d.copy_bytes&&g.maximum_capacity_bytes>=d.capacity_bytes&&g.maximum_release_bytes>=d.release_bytes&&g.maximum_depth>=d.depth}
fn bytes<T>(count:usize)->Result<usize,ValueError>{count.checked_mul(size_of::<T>()).ok_or_else(||invalid("canonical mesh capacity overflows"))}
fn object(value:&DslValue)->Result<&[(String,DslValue)],ValueError>{match value{DslValue::Object(values)=>Ok(values),_=>Err(invalid("canonical mesh requires an object"))}}
fn object_mut(value:&mut DslValue)->Result<&mut [(String,DslValue)],ValueError>{match value{DslValue::Object(values)=>Ok(values),_=>Err(invalid("canonical mesh requires an object"))}}
fn array(value:&DslValue)->Result<&[DslValue],ValueError>{match value{DslValue::Array(values)=>Ok(values),_=>Err(invalid("canonical mesh requires an array"))}}
fn text(value:&DslValue)->Result<&str,ValueError>{match value{DslValue::String(value)=>Ok(value),_=>Err(invalid("canonical mesh requires text"))}}
fn name_demand(value:&str,position:usize)->RetirementDemand{RetirementDemand{copy_bytes:value.get(position..).and_then(|value|value.chars().next()).map_or(0,char::len_utf8),depth:1,..Default::default()}}
fn name_step(value:&str,position:&mut usize,count:&mut usize)->Result<(bool,RetainedCloneProgress),ValueError>{let d=name_demand(value,*position);if let Some(value)=value.get(*position..).and_then(|value|value.chars().next()){*position+=value.len_utf8();*count+=1;if *count>128{return Err(invalid("canonical mesh name exceeds 128 characters"))}}else if *count==0{return Err(invalid("canonical mesh name is empty"))}Ok((*position==value.len(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
fn move_value(value:&mut DslValue)->DslValue{std::mem::replace(value,DslValue::Null)}
fn move_text(value:&mut DslValue)->Result<String,ValueError>{if !matches!(value,DslValue::String(_)){return Err(invalid("canonical mesh text ownership is absent"))}match move_value(value){DslValue::String(value)=>Ok(value),_=>unreachable!()}}
fn move_array(value:&mut DslValue)->Result<Vec<DslValue>,ValueError>{if !matches!(value,DslValue::Array(_)){return Err(invalid("canonical mesh array ownership is absent"))}match move_value(value){DslValue::Array(value)=>Ok(value),_=>unreachable!()}}
trait Scalar:Copy{fn decode(value:&DslValue)->Result<Self,ValueError>;}
impl Scalar for f32{fn decode(value:&DslValue)->Result<Self,ValueError>{let DslValue::Number(value)=value else{return Err(invalid("canonical mesh float is absent"))};let value=value.as_f64();if !value.is_finite()||value.abs()>f32::MAX as f64{return Err(invalid("canonical mesh float is outside Float32"))}Ok(value as f32)}}
impl Scalar for u32{fn decode(value:&DslValue)->Result<Self,ValueError>{let DslValue::Number(value)=value else{return Err(invalid("canonical mesh index is absent"))};value.as_u64().and_then(|value|u32::try_from(value).ok()).ok_or_else(||invalid("canonical mesh index is outside UInt32"))}}
impl Scalar for u8{fn decode(value:&DslValue)->Result<Self,ValueError>{let DslValue::Number(value)=value else{return Err(invalid("canonical mesh byte is absent"))};value.as_u64().and_then(|value|u8::try_from(value).ok()).ok_or_else(||invalid("canonical mesh byte is outside UInt8"))}}
fn numeric_demand<T:Scalar>(source:&DslValue,target:&Vec<T>,index:usize,reserved:bool)->Result<RetirementDemand,ValueError>{let source=array(source)?;Ok(if !reserved{RetirementDemand{capacity_bytes:bytes::<T>(source.len())?,depth:1,..Default::default()}}else{RetirementDemand{copy_bytes:if index<source.len(){size_of::<Number>()+size_of::<T>()}else{0},depth:1,..Default::default()}})}
fn numeric_step<T:Scalar>(source:&DslValue,target:&mut Vec<T>,index:&mut usize,reserved:&mut bool)->Result<(bool,RetainedCloneProgress),ValueError>{let source=array(source)?;let mut p=RetainedCloneProgress{copied_items:1,..Default::default()};if !*reserved{if !target.is_empty()||target.capacity()!=0{return Err(invalid("canonical mesh reservation target is not empty"))}target.try_reserve_exact(source.len()).map_err(|_|invalid("canonical mesh reservation failed"))?;p.retained_capacity_bytes=bytes::<T>(target.capacity())?;*reserved=true;return Ok((false,p))}if *index<source.len(){target.push(T::decode(&source[*index])?);*index+=1;p.copied_bytes=size_of::<Number>()+size_of::<T>();return Ok((false,p))}Ok((true,p))}
fn compare_demand(left:&String,right:&String,position:usize,body:usize)->Result<RetirementDemand,ValueError>{let remaining=left.len().min(right.len()).saturating_sub(position);Ok(RetirementDemand{copy_bytes:if remaining==0{0}else{remaining.min((body/2).max(1))*2},depth:1,..Default::default()})}
fn compare_step(left:&String,right:&String,position:usize,grant:RetainedCloneGrant)->Result<(Option<Ordering>,usize,RetainedCloneProgress),ValueError>{let d=compare_demand(left,right,position,grant.maximum_copy_bytes)?;if !admitted(d,grant){return Ok((None,position,Default::default()))}let count=d.copy_bytes/2;let end=position+count;let order=left.as_bytes()[position..end].cmp(&right.as_bytes()[position..end]);let done=order!=Ordering::Equal||end==left.len().min(right.len());Ok((done.then(||if order==Ordering::Equal{left.len().cmp(&right.len())}else{order}),end,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
fn insertion<V:RetireOwned>(pending:&mut HistoryFoldIndexInsert<String,V>,target:&mut HistoryFoldIndex<String,V>,grant:RetainedCloneGrant)->Result<(bool,RetainedCloneProgress),ValueError>{let(ready,p)=pending.step(target,grant,compare_step)?;if !ready||p!=Default::default(){return Ok((false,p))}let(slot,p)=pending.commit_with(target,grant,|value|value)?;Ok((slot.is_some(),p))}
#[derive(semio_framework_value_derive::RetireOwned)]
struct Record{key:Option<String>,source:Option<DslValue>,scan:usize,seen:u8,domain:Option<MeshAttributeDomain>,semantic:Option<MeshAttributeSemantic>,interpolation:Option<MeshAttributeInterpolation>,values:Option<Vec<DslValue>>,indices:Option<Vec<u32>>,mime:Option<String>,data:Vec<u8>,labels:Vec<String>,index:usize,reserved:bool,numeric:Option<usize>,name_position:usize,name_chars:usize,name_ready:bool}
impl Record{fn new(key:String,source:DslValue)->Self{Self{key:Some(key),source:Some(source),scan:0,seen:0,domain:None,semantic:None,interpolation:None,values:None,indices:None,mime:None,data:Vec::new(),labels:Vec::new(),index:0,reserved:false,numeric:None,name_position:0,name_chars:0,name_ready:false}}}
#[derive(semio_framework_value_derive::RetireOwned)]
#[value(send_only)]
struct State{source:Option<DslValue>,mesh:Option<MeshData>,origin:(u64,u64),scan:usize,seen:u16,field:Option<usize>,index:usize,reserved:bool,row:usize,record:Option<Record>,record_close:Option<ControlledRetirement<Record>>,record_done:bool,attributes:Option<HistoryFoldIndexInsert<String,MeshAttribute>>,materials:Option<HistoryFoldIndexInsert<String,DslValue>>,textures:Option<HistoryFoldIndexInsert<String,MeshTexture>>,references:Vec<(String,Vec<String>)>,references_reserved:bool,validate_domain:usize,validate_index:usize,finished:bool}
