 pub fn ready(&self)->bool{self.state.as_ref().is_some_and(|state|state.finished)}
 pub fn take(&mut self,cx:&mut StepContext<'_>)->Result<Option<MeshData>,OriginalTurnFailure>{if cx.is_cancelled()||cx.should_yield()||cx.retained_grant().maximum_items==0||cx.retained_grant().maximum_depth==0||!self.ready(){return Ok(None)}cx.consume_fuel(1);if self.origin!=(cx.operation().0,cx.generation().0){return Err(invalid("canonical mesh transfer initiating operation changed").into())}let value=self.state.as_mut().unwrap().mesh.take();if let Err(error)=cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()}){self.state.as_mut().unwrap().mesh=value;return Err(error.into())}Ok(value)}
 pub fn begin_close(&mut self){if self.close.is_none(){if let Some(state)=self.state.take(){self.close=Some(ControlledRetirement::new(state).unwrap_or_else(|_|unreachable!()))}}}
 pub fn next_close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{self.close.as_ref().map_or(Ok(Default::default()),|close|close.selected_demand(body))}
 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{if !self.terminal_is_empty()&&self.origin!=(cx.operation().0,cx.generation().0){if cx.should_yield(){return Ok(InteractiveJobCloseStep::Blocked)}cx.consume_fuel(1);return Err(invalid("canonical mesh close initiating operation changed").into())}self.begin_close();if self.terminal_is_empty(){return Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}let d=self.next_close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=semio_framework_job::close_original_retained_step(cx,d,|grant|self.close.as_mut().unwrap().step(grant))?;if self.close.as_ref().is_some_and(|close|close.terminal_is_empty()){self.close=None}Ok(step)}
 pub fn terminal_is_empty(&self)->bool{self.state.is_none()&&self.close.is_none()}
