impl Drop for MeshCanonicalDecoder{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"canonical mesh decoder must retain original source through full close");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.state)}}}}

